package br.com.adminpool.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="pedidos_produto")
public class PedidoProduto {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Cliente cliente; @ManyToOne private Piscina piscina; @ManyToOne private Produto produto; @Column(nullable=false) private Integer quantidade; @Column(nullable=false,precision=12,scale=2) private BigDecimal valorUnitario; @Column(precision=12,scale=2) private BigDecimal precoCompraUnitario; private Long codigoPedido; private LocalDate dataPedido=LocalDate.now(); private LocalDate dataConclusao; private String status="SOLICITADO"; @Enumerated(EnumType.STRING) private ResponsavelPagamento pagador; private boolean financeiroLancado=false;
 public BigDecimal getTotalCompra(){return (precoCompraUnitario==null?BigDecimal.ZERO:precoCompraUnitario).multiply(BigDecimal.valueOf(quantidade==null?0:quantidade));} public BigDecimal getTotalVenda(){return (valorUnitario==null?BigDecimal.ZERO:valorUnitario).multiply(BigDecimal.valueOf(quantidade==null?0:quantidade));}
 public Long getId(){return id;} public void setId(Long v){id=v;} public Cliente getCliente(){return cliente;} public void setCliente(Cliente v){cliente=v;} public Piscina getPiscina(){return piscina;} public void setPiscina(Piscina v){piscina=v;} public Produto getProduto(){return produto;} public void setProduto(Produto v){produto=v;} public Integer getQuantidade(){return quantidade;} public void setQuantidade(Integer v){quantidade=v;} public BigDecimal getValorUnitario(){return valorUnitario;} public void setValorUnitario(BigDecimal v){valorUnitario=v;} public BigDecimal getPrecoCompraUnitario(){return precoCompraUnitario;} public void setPrecoCompraUnitario(BigDecimal v){precoCompraUnitario=v;} public Long getCodigoPedido(){return codigoPedido;} public void setCodigoPedido(Long v){codigoPedido=v;} public LocalDate getDataPedido(){return dataPedido;} public void setDataPedido(LocalDate v){dataPedido=v;} public LocalDate getDataConclusao(){return dataConclusao;} public void setDataConclusao(LocalDate v){dataConclusao=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public ResponsavelPagamento getPagador(){return pagador;} public void setPagador(ResponsavelPagamento v){pagador=v;} public boolean isFinanceiroLancado(){return financeiroLancado;} public void setFinanceiroLancado(boolean v){financeiroLancado=v;}
}
